          x: {
            type: 'linear', min: 0, max: 1,
            title: { display: isBottomRow, text: 'Input, x', color: '#222', font: { size: 12, style: 'italic' } },
            ticks: { display: isBottomRow, stepSize: 0.5, color: '#333', font: { size: 10 } },
            grid: { display: false }
          },
          y: {
            min: -1, max: 1,
            title: { display: isLeftCol, text: 'Output, y', color: '#222', font: { size: 12, style: 'italic' } },
            ticks: { display: isLeftCol, stepSize: 1, color: '#333', font: { size: 10 } },
            grid: { display: false }
          }
        }
      },
      plugins: [{
        id: 'panelTag',
        afterDraw: function (ch) {
          var ctx = ch.ctx, a = ch.chartArea;
          ctx.save();
          ctx.fillStyle = '#222';
          ctx.font = '13px sans-serif';
          ctx.textAlign = 'left';
          ctx.fillText(PANEL_LABELS[idx], a.left - 14, a.top + 2);
          ctx.restore();
        }
      }]
