userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<p id="demoNarration" style="margin:0;font-size:10px;max-width:180px">Panel (a) shows the target: a smooth black curve sampled at 10 noisy orange points. Every other panel shows a one-hidden-layer network trained to fit these same points.</p>
<div style="display:flex;align-items:center;gap:4px">
  <button onclick="prevStep()">◀</button> <span id="stepLabel">1 / 4</span> <button onclick="nextStep()">▶</button>
</div>
<label>Number of hidden units: <output id="hiddenUnitsVal">50</output>
<input id="hiddenUnitsInput" type="range" min="0" max="4" step="1" value="4" oninput="update_hiddenUnits(+this.value)"></label>
<label><input id="fitContrastInput" type="checkbox" checked onchange="toggle_fitContrast(this.checked)"> High capacity (50 units)</label>
<span style="font-size:10px;color:#555">Click any panel to inspect the fit.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var CAPACITIES = [6, 7, 8, 10, 50];
var PANEL_LABELS = ['a)', 'b)', 'c)', 'd)', 'e)', 'f)'];
var PANEL_TITLES = ['', '6 hidden units', '7 hidden units', '8 hidden units', '10 hidden units', '50 hidden units'];

function truth(x) {
  return 0.55 * Math.exp(-Math.pow((x - 0.25) / 0.17, 2))
       - 0.50 * Math.exp(-Math.pow((x - 0.80) / 0.25, 2)) - 0.12;
}

// 10 shared noisy data points — evenly spaced like the source
var DATA_PTS = [
  [0.02, -0.08], [0.12, 0.13], [0.17, 0.40], [0.22, 0.44], [0.78, -0.62],
  [0.86, -0.42], [0.90, -0.38], [0.93, -0.44], [0.96, -0.40], [0.98, -0.48]
];

var FIT_KNOTS = {
  6:  [[0,-0.28],[0.08,-0.02],[0.16,0.22],[0.24,0.5],[0.3,1.6],[0.4,1.35],[0.47,0.2],[0.55,-1.7],[0.66,-1.6],[0.74,-0.55],[0.82,-0.55],[0.87,-0.32],[0.92,-0.42],[1,-0.35]],
  7:  [[0,-0.28],[0.1,0.05],[0.2,0.38],[0.33,0.85],[0.42,0.45],[0.55,-0.1],[0.65,-0.75],[0.72,-1.3],[0.8,-0.6],[0.87,-0.32],[0.93,-0.42],[1,-0.4]],
  8:  [[0,-0.26],[0.1,0.05],[0.2,0.4],[0.28,0.76],[0.38,0.58],[0.5,0.0],[0.62,-0.5],[0.74,-0.84],[0.84,-0.42],[0.9,-0.3],[0.95,-0.45],[1,-0.4]],
  10: [[0,-0.22],[0.12,0.14],[0.22,0.42],[0.28,0.56],[0.4,0.32],[0.55,-0.15],[0.68,-0.48],[0.8,-0.56],[0.88,-0.42],[0.95,-0.45],[1,-0.34]],
  50: null
};

function piecewise(knots, x) {
  if (x <= knots[0][0]) return knots[0][1];
  for (var i = 1; i < knots.length; i++) {
    if (x <= knots[i][0]) {
      var t = (x - knots[i-1][0]) / (knots[i][0] - knots[i-1][0]);
      return knots[i-1][1] + t * (knots[i][1] - knots[i-1][1]);
    }
  }
  return knots[knots.length-1][1];
}

function fitFn(cap) {
  if (cap === 50) return function (x) { return truth(x) + 0.07 * Math.sin((x - 0.3) * 6) * Math.exp(-Math.pow((x-0.55)/0.45, 2)); };
  var knots = FIT_KNOTS[cap];
  return function (x) { return piecewise(knots, x); };
}

function sampleCurve(fn, n) {
  var pts = [];
  for (var i = 0; i < n; i++) pts.push({ x: i / (n - 1), y: fn(i / (n - 1)) });
  return pts;
}

var truthPts = sampleCurve(truth, 120);
var scatterPts = DATA_PTS.map(function (p) { return { x: p[0], y: p[1] }; });

var grid = document.createElement('div');
grid.style.cssText = 'width:100%;height:100%;display:grid;grid-template-columns:1fr 1fr 1fr;grid-template-rows:1fr 1fr;gap:10px 8px;';
document.getElementById('container').appendChild(grid);

var cells = [], charts = [];
var POPUPS = [
  ['Panel a — the task', 'The black curve is the smooth ground truth; the orange points are 10 noisy samples. Every network in panels b–f is trained on these same points.'],
  ['6 hidden units', 'The teal fit passes near the points but develops huge overshoots and kinks between them — too little capacity yields an unstable solution.'],
  ['7 hidden units', 'Still overshooting the peak (~0.8) and plunging below −1 near x≈0.7. One more unit helps only a little.'],
  ['8 hidden units', 'The fit tracks the data more closely but remains piecewise-linear with visible kinks and a trough that is too deep.'],
  ['10 hidden units', 'The teal curve is now close to the black ground truth, with only mild deviations between the points.'],
  ['50 hidden units', 'Ample capacity: training finds a smooth, simple function consistent with the data that generalizes well between points.']
];

for (var p = 0; p < 6; p++) {
  (function (idx) {
    var cell = document.createElement('div');
    cell.style.cssText = 'position:relative;min-width:0;min-height:0;cursor:pointer;border:2px solid transparent;border-radius:4px;';
    var cv = document.createElement('canvas');
    cv.style.cssText = 'width:100%;height:100%;display:block';
    cell.appendChild(cv);
    grid.appendChild(cell);
    cells.push(cell);

    // Panel letter tag: HTML overlay, top-left corner, clear of axes and tick labels
    var tag = document.createElement('div');
    tag.textContent = PANEL_LABELS[idx];
    tag.style.cssText = 'position:absolute;top:-2px;left:-2px;font:600 14px sans-serif;color:#222;pointer-events:none;background:rgba(255,255,255,0.85);padding:0 2px;line-height:1.1;z-index:2;';
    cell.appendChild(tag);

    var datasets = [
      { label: 'Ground truth', data: truthPts, borderColor: '#111', borderWidth: 2.5, pointRadius: 0, showLine: true, tension: 0.3 },
      { label: 'Data', data: scatterPts, type: 'scatter', pointRadius: 4, pointBackgroundColor: '#d97b54', pointBorderColor: '#d97b54' }
    ];
    if (idx > 0) {
      datasets.splice(1, 0, {
        label: 'Network fit', data: sampleCurve(fitFn(CAPACITIES[idx - 1]), 160),
        borderColor: '#8fd0c8', borderWidth: 2.5, pointRadius: 0, showLine: true, tension: 0
      });
    }

    var isLeftCol = (idx % 3 === 0);
    var isBottomRow = (idx >= 3);
    var chart = new Chart(cv.getContext('2d'), {
      type: 'line',
      data: { datasets: datasets },
      options: {
        responsive: true, maintainAspectRatio: false,
        animation: false,
        layout: { padding: { top: 22, left: 2, right: 2 } },
        interaction: { mode: 'nearest', intersect: false },
        plugins: {
          legend: { display: false },
          title: {
            display: idx > 0, text: PANEL_TITLES[idx], color: '#222',
            padding: { top: 0, bottom: 4 },
            font: { size: 15, weight: '600', family: 'sans-serif' }
          },
          tooltip: {
            callbacks: {
              label: function (c) { return c.dataset.label + '  (' + c.parsed.x.toFixed(2) + ', ' + c.parsed.y.toFixed(2) + ')'; }
            }
          }
        },
        scales: {
          x: {
            type: 'linear', min: 0, max: 1,
            title: { display: isBottomRow, text: 'Input, x', color: '#222', font: { size: 12, style: 'italic' } },
            ticks: {
              // Labels only on bottom row; tick marks kept on every panel via drawTicks
              display: isBottomRow,
              stepSize: 0.5, color: '#333', font: { size: 10 },
              callback: function (v) { return v.toFixed(1); },
              autoSkip: false
            },
            grid: { display: false, drawTicks: true, tickLength: 4, tickColor: '#333' }
          },
          y: {
            min: -1, max: 1,
            title: { display: isLeftCol, text: 'Output, y', color: '#222', font: { size: 12, style: 'italic' } },
            ticks: {
              // Labels only on left column; tick marks kept on every panel
              display: isLeftCol,
              stepSize: 1, color: '#333', font: { size: 10 },
              callback: function (v) { return v.toFixed(1); },
              autoSkip: false
            },
            grid: { display: false, drawTicks: true, tickLength: 4, tickColor: '#333' }
          }
        }
      }
    });
    charts.push(chart);

    cell.addEventListener('click', function () {
      showPopup(POPUPS[idx][0], POPUPS[idx][1]);
      if (idx > 0) update_hiddenUnits(idx - 1);
    });
  })(p);
}

var activeIdx = 4;
var engaged = false; // default view = faithful, full-opacity, no highlight

function refreshHighlight() {
  for (var i = 0; i < 6; i++) {
    var isActive = (i === activeIdx + 1);
    if (engaged) {
      cells[i].style.border = isActive ? '2px solid #2a9d8f' : '2px solid transparent';
      cells[i].style.opacity = (i === 0 || isActive) ? '1' : '0.45';
    } else {
      cells[i].style.border = '2px solid transparent';
      cells[i].style.opacity = '1';
    }
  }
  document.getElementById('hiddenUnitsVal').value = CAPACITIES[activeIdx];
  document.getElementById('hiddenUnitsInput').value = activeIdx;
  document.getElementById('fitContrastInput').checked = (activeIdx === 4);
}

function update_hiddenUnits(v) {
  activeIdx = Math.max(0, Math.min(4, v | 0));
  engaged = true;
  refreshHighlight();
}

function toggle_fitContrast(on) {
  update_hiddenUnits(on ? 4 : 0);
}

var DEMO_STEPS = [
  { title: 'The data and the task', narration: 'Panel (a) shows the target: a smooth black curve sampled at 10 noisy orange points. Every other panel shows a one-hidden-layer network trained to fit these same points.', hiddenUnits: 4, contrast: true },
  { title: 'Too little capacity', narration: 'With only 6 hidden units the fitted teal curve still passes near the points but develops huge overshoots and kinks between them — the network lacks the capacity to represent a smooth solution and settles on an unstable one.', hiddenUnits: 0, contrast: false },
  { title: 'Growing capacity', narration: 'Drag the slider through 7, 8, and 10 units: the spikes shrink, the kinks soften, and the fitted curve progressively hugs the black ground truth.', hiddenUnits: 3, contrast: false },
  { title: 'Ample capacity', narration: 'At 50 hidden units the teal curve is smooth and closely tracks the ground truth — plenty of capacity lets training find a simple, smooth function consistent with the data.', hiddenUnits: 4, contrast: true }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(DEMO_STEPS.length - 1, i));
  var s = DEMO_STEPS[stepIdx];
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + DEMO_STEPS.length;
  if (i === 0 && stepIdx === 0 && !engaged) {
    activeIdx = s.hiddenUnits;
    refreshHighlight();
  } else {
    update_hiddenUnits(s.hiddenUnits);
  }
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

// Step 0 default: full-opacity faithful view, no highlight
activeIdx = 4;
engaged = false;
refreshHighlight();
document.getElementById('demoNarration').textContent = DEMO_STEPS[0].narration;
document.getElementById('stepLabel').textContent = '1 / ' + DEMO_STEPS.length;
window.__markRendered();
// @FIGURE_CODE_END

